"""Deterministic static build. Run with Python 3. No build dependencies."""
from pathlib import Path
from html import escape
import sys, json, shutil
ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'src'))
from content import TREATMENTS, TEAM
OUT=ROOT/'dist'; OUT.mkdir(exist_ok=True)
E=escape
PAGES=[]
def img(name,alt,cls='',eager=False):
    return f'<img class="{cls}" src="/assets/{name}.webp" alt="{E(alt)}" width="600" height="450" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def button(text,url,secondary=False): return f'<a class="button{" secondary" if secondary else ""}" href="{url}">{text}</a>'
def breadcrumb(label,parent=None):
    mid=f'<li><a href="/{parent[0]}/">{parent[1]}</a></li>' if parent else ''
    return f'<nav class="breadcrumbs wrap" aria-label="Breadcrumb"><ol><li><a href="/">Home</a></li>{mid}<li aria-current="page">{E(label)}</li></ol></nav>'
def intro(kicker,title,text): return f'<div class="page-intro wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lede">{text}</p></div>'
def cta(): return '<section class="cta"><div class="wrap cta-inner"><div><p class="eyebrow">Your next step</p><h2>Let’s talk about your care.</h2><p>Speak with our team about an appointment at Wilton Dental.</p></div>'+button('Contact the practice','/contact/')+'</div></section>'
MAP_SRC='https://maps.google.com/maps?q=wilton%20Dental%20Practice%2C%2063a%20Wilton%20Road%2C%20London%2C%20SW1V%201DE&t=m&z=16&output=embed&iwloc=near'
MAP_DIRECTIONS='https://maps.google.com/maps?q=wilton%20Dental%20Practice%2C%2063a%20Wilton%20Road%2C%20London%2C%20SW1V%201DE'
def location():
    # Reuse the exact embed query from the public practice homepage.
    return f'''<section id="location" class="location-section"><div class="wrap location-grid"><div><p class="eyebrow">Find Wilton Dental</p><h2>Right here<br>in Victoria.</h2><address>63a Wilton Road<br>Victoria, London<br>SW1V 1DE</address><div class="actions">{button('Get directions',MAP_DIRECTIONS)}{button('Contact the practice','/contact/',True)}</div><h3>Before setting off</h3><p>Confirm your appointment time and any access requirements with the team. Ask about evening and weekend availability.</p></div><div><div class="map-panel"><iframe loading="lazy" src="{E(MAP_SRC,quote=True)}" title="Google Map: Wilton Dental Practice, 63a Wilton Road, London, SW1V 1DE" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe></div><p class="map-caption">Wilton Dental Practice · 63a Wilton Road<br><a href="{E(MAP_DIRECTIONS,quote=True)}">Open the location in Google Maps</a></p></div></div></section>'''
def journey():
    steps=[('Listen','Start with a conversation','Tell us what’s bothering you, what you’d like to change and what would make care feel easier.'),('Understand','See the full picture','A careful assessment, supported by on-site imaging where it helps us plan with precision.'),('Choose','Decide with confidence','Clear options, transparent next steps and enough time to make the right decision for you.'),('Care','Feel supported throughout','One welcoming team, considerate follow-up and a plan designed around real life.')]
    items=''.join(f'<li class="journey-step"><span class="step-dot" aria-hidden="true">{i:02d}</span><div class="step-copy"><p class="eyebrow">{label}</p><h3>{title}</h3><p>{copy}</p></div></li>' for i,(label,title,copy) in enumerate(steps,1))
    return '<section class="section journey" id="journey"><div class="wrap journey-grid"><div class="journey-intro"><p class="eyebrow">A calmer way to care</p><h2>Know what<br><em>happens next.</em></h2><p>Good dentistry starts with feeling heard. We make space for questions, explain the choices in plain English and never rush the decision.</p><a class="text-link" href="/contact/">Start your conversation</a></div><ol class="timeline" id="timeline">'+items+'</ol></div></section>'
def treatment_card(t):
    return f'<article class="treatment-card" data-category="{E(t["category"])}"><a href="/treatments/{t["slug"]}/">{img(t["image"],t["alt"])}<div class="card-copy"><p class="eyebrow">{t["category"]}</p><h3>{t["title"]}</h3><p>{t["intro"]}</p><span class="text-link">Explore treatment</span></div></a></article>'
def team_card(t):
    return f'<article class="team-card"><a href="/team/{t["slug"]}/">{img(t["image"],t["name"])}<h3>{t["name"]}</h3><p>{t["role"]}</p><span class="text-link">View profile</span></a></article>'
def tooth():
    return '''<div class="tooth-viewer" data-tooth-viewer><div class="tooth-stage"><img class="tooth-poster" src="/assets/tooth-poster.webp" alt="Illustrative ceramic tooth sculpture" width="680" height="740" loading="lazy"><div class="tooth-canvas" aria-hidden="true"></div><span class="viewer-label">A closer look</span></div><div class="viewer-controls" hidden><button type="button" data-rotate="-1" aria-label="Rotate tooth left">Rotate left</button><button type="button" data-auto aria-pressed="false">Play rotation</button><button type="button" data-rotate="1" aria-label="Rotate tooth right">Rotate right</button><button type="button" data-reset>Reset view</button></div><p class="viewer-status" role="status">Illustrative tooth sculpture. Not a diagnostic scan.</p></div>'''
def page(slug,title,description,body,active='',viewer=False):
    nav=[('about','Our practice'),('treatments','Treatments'),('team','Our team'),('imaging','Imaging'),('care','NHS & private'),('fees','Fees'),('contact','Contact')]
    links=''.join(f'<a href="/{s}/"'+(' aria-current="page"' if active==s else '')+f'>{l}</a>' for s,l in nav)
    footerlinks=''.join(f'<a href="/{s}/">{l}</a>' for s,l in nav)
    html=f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | Wilton Dental Practice</title><meta name="description" content="{E(description,quote=True)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#143b59"><link rel="icon" href="/assets/wilton-original-logo.png"><link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script>{'<script type="importmap">{"imports":{"three":"/assets/vendor/three.module.min.js"}}</script>' if viewer else ''}</head><body><a class="skip-link" href="#main">Skip to content</a><div class="topbar"><div class="wrap"><span>Victoria, London · NHS, independent & private care</span><a href="tel:+442078346361">020 7834 6361</a></div></div><header class="site-header"><div class="wrap header-inner"><a class="brand" href="/" aria-label="Wilton Dental Practice home"><img src="/assets/wilton-original-logo.png" alt="" width="262" height="239"><span>Wilton Dental<small>Practice · Victoria, London</small></span></a><button class="menu-toggle" type="button" aria-controls="main-nav" aria-expanded="false" hidden>Menu</button><nav id="main-nav" class="main-nav" aria-label="Main navigation">{links}</nav></div></header><main id="main">{body}</main><footer class="site-footer"><div class="wrap footer-grid"><div><a class="footer-name" href="/">Wilton Dental Practice</a><p>63a Wilton Road<br>Victoria, London SW1V 1DE</p><a href="tel:+442078346361">020 7834 6361</a><a href="mailto:info@wiltondental.co.uk">info@wiltondental.co.uk</a></div><nav aria-label="Footer navigation"><h2>Explore</h2>{footerlinks}</nav><div><h2>Plan your visit</h2><p>Contact the team for current appointment availability, including evening and weekend options.</p><a href="https://wa.me/447378776626">Message on WhatsApp</a><a href="/contact/#location">Find us in Victoria</a></div></div><div class="wrap footer-bottom"><span>© 2026 Wilton Dental Practice</span><span>Website redesign preview</span><a href="/privacy/">Privacy & website information</a></div></footer></body></html>'''
    dest=OUT/(slug+'/index.html' if slug else 'index.html');dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(html,encoding='utf-8')
    PAGES.append(dict(path='/'+slug+'/' if slug else '/',title=title,description=description,file=dest.relative_to(OUT).as_posix()))

home='''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><p class="eyebrow">Your dentist in the heart of Victoria</p><h1>Care for your smile.<br><em>Time for you.</em></h1><p class="lede">From everyday check-ups to a new chapter for your smile. Personal dental care, with a team who takes time to listen.</p><div class="actions">'''+button('Arrange a visit','/contact/')+button('Explore treatments','/treatments/',True)+'''</div><div class="hero-note"><span>Find us</span><p>63a Wilton Road, London SW1V 1DE</p></div></div><figure class="hero-visual">'''+img('practice','Treatment room shown on the Wilton Dental Practice website',eager=True)+'''<figcaption><strong>A welcoming space in Victoria</strong><span>Ask about evening & weekend appointments</span></figcaption></figure></div></section><section class="care-strip"><div class="wrap"><div><span>01</span><p>Everyday care<br><strong>NHS, independent & private</strong></p></div><div><span>02</span><p>A personal approach<br><strong>Discuss your options, at your pace</strong></p></div><div><span>03</span><p>Easy to reach<br><strong>Close to Victoria station</strong></p></div></div></section><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">Treatment, thoughtfully considered</p><h2>Care for every<br>kind of smile.</h2></div><div><p>Keep your mouth healthy, restore what’s missing or explore a change. Start with the care that matters to you.</p><a class="text-link" href="/treatments/">View all treatments</a></div></div><div class="cards">'''+''.join(treatment_card(TREATMENTS[i]) for i in [0,1,2,3,4,5])+'''</div></section><section class="precision"><div class="wrap precision-grid"><div class="precision-copy"><p class="eyebrow">Imaging & considered planning</p><h2>Art meets<br><em>precision.</em></h2><p>Good care begins with a clear picture. Explore the practice’s digital imaging services and the role they play in treatment planning.</p>'''+button('Explore our imaging','/imaging/',True)+'''</div>'''+tooth()+'''</div></section><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">People behind your care</p><h2>Meet the Wilton team.</h2></div><p>Clinical care and a friendly welcome, supported by our dental and practice team.</p></div><div class="team-grid home-team">'''+''.join(team_card(t) for t in TEAM)+'''</div></section><section class="statement"><div class="wrap"><h2>Precision in every detail.<br><em>Comfort at every step.</em></h2></div></section><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">A clear first step</p><h2>Your visit, made simpler.</h2></div><a class="text-link" href="/about/">Get to know the practice</a></div><ol class="steps"><li><span>01</span><h3>Tell us what you need</h3><p>Speak with the team about your concerns, availability and the care you’re looking for.</p></li><li><span>02</span><h3>Understand your options</h3><p>Your clinician can assess your oral health and explain appropriate treatment choices.</p></li><li><span>03</span><h3>Decide with confidence</h3><p>Discuss your plan, costs and questions before deciding how to proceed.</p></li></ol></section>'''+cta()
