home=expressive_hero+home[home.index('<section class="care-strip">'):]
home=home.replace('<section class="section wrap"><div class="section-heading"><div><p class="eyebrow">Treatment', '<section id="treatments" class="section wrap"><div class="section-heading"><div><p class="eyebrow">Treatment',1)
