fees=breadcrumb('Fees & finance')+intro('Fees & finance','Clear conversations<br>about cost.','Ask for a written estimate that explains your proposed treatment and what is included.')+'<section class="section compact wrap article-layout"><article><h2>Confirm current fees with the team</h2><p>Your treatment plan and cost depend on your individual assessment. The practice publishes selected prices and promotional offers, but a complete, current fee schedule is not available in this preview.</p><div class="fee-table"><table><caption>Services to discuss with the practice</caption><thead><tr><th scope="col">Service</th><th scope="col">What to confirm</th></tr></thead><tbody><tr><th scope="row">Examinations & everyday care</th><td>Care pathway, appointment fee and treatment estimate</td></tr><tr><th scope="row">Dental implants</th><td>Assessment, imaging, placement, restoration and any additional treatment</td></tr><tr><th scope="row">Teeth whitening</th><td>Current product, suitability and what the package includes</td></tr><tr><th scope="row">OPG & CBCT imaging</th><td>Scan type, current fee, reporting and image delivery</td></tr><tr><th scope="row">Skin & wellbeing services</th><td>Provider, consultation fee, treatment and follow-up</td></tr></tbody></table></div><h2>Finance enquiries</h2><p>The existing practice website advertises dental finance. Ask the team whether finance is currently offered, which treatments qualify and the applicable eligibility requirements and terms before relying on an offer.</p></article><aside class="side-panel"><h2>Discuss your estimate</h2><p>The team can explain the costs relevant to your treatment enquiry.</p>'+button('Contact the practice','/contact/')+'<a href="/care/">NHS & private care</a></aside></section>'+cta()
page('fees','Fees & finance','Discuss treatment estimates, fees and current finance arrangements with Wilton Dental Practice.',fees,'fees')

